  "done": false,
  "designs": [
    {
      "widths": [186, 280, 47, 91, 154],
      "idea": "Test a middle ground between s0A and S: retain intact identifiers and suppliers while checking whether a modest reduction in description width preserves natural two-line breaks."
    },
    {
      "widths": [120, 110, 47, 80, 102],
      "idea": "Test a fitting layout that gives identifiers and suppliers more room than Q while retaining usable quantity and price columns. Some identifiers and supplier names will still split, so judge the resulting breaks and row heights."
    },
    {
      "widths": [140, 128, 47, 80, 110],
      "idea": "Test a moderate-scrolling compromise with more room for part numbers, descriptions and suppliers than a fitting layout can provide. Check whether the remaining fragmentation and increased height justify the reduced horizontal travel."
    }
  ]
